export function getCategoryGroup(category: string): 'beam_a' | 'beam_b' {
  const lower = category.toLowerCase();
  if (
    lower.includes('genre') || 
    lower.includes('rock') || 
    lower.includes('metal') || 
    lower.includes('punk') || 
    lower.includes('hip hop') || 
    lower.includes('rap') || 
    lower.includes('house') || 
    lower.includes('techno') || 
    lower.includes('jazz') || 
    lower.includes('decade') || 
    lower.includes('rhythm') ||
    lower.includes('groove') ||
    lower.includes('world')
  ) {
    return 'beam_a';
  }
  return 'beam_b';
}

export function getCategoryColor(category: string): string {
  const lower = category.toLowerCase();
  if (lower.includes('suno') || lower.includes('stack') || lower.includes('template')) return '#F59E0B'; // Amber
  if (lower.includes('synth')) return '#06B6D4'; // Cyan
  if (lower.includes('drum')) return '#EF4444'; // Red
  if (lower.includes('vocal')) return '#A855F7'; // Purple
  if (lower.includes('string') || lower.includes('guitar')) return '#10B981'; // Emerald
  if (lower.includes('piano') || lower.includes('key')) return '#3B82F6'; // Blue
  if (lower.includes('wind') || lower.includes('brass')) return '#F97316'; // Orange
  if (lower.includes('odd') || lower.includes('anomal')) return '#EC4899'; // Pink
  if (lower.includes('production') || lower.includes('spatial')) return '#8B5CF6'; // Violet
  return '#14B8A6'; // Teal
}

export function sanitizeId(str: string): string {
  return str.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '');
}


